canonical=json.loads((root/'docs/evidence/2026-09-11-v1-05c2e2a-role-tree-supervision.json').read_text())
assert canonical['whole_v1_complete'] is False
reports=[]
for ref in canonical['evidence_references']:
 path=bases[ref['repo']]/ref['path']; raw=path.read_bytes()
 assert hashlib.sha256(raw).hexdigest()==ref['sha256'],str(path)
 if path.suffix=='.json': reports.append((str(path),json.loads(raw)))
