checked=0
for repo,files in inv['final_files'].items():
 commit=canonical['code_commits'][repo]
 assert re.fullmatch('[0-9a-f]{40}',commit)
 assert subprocess.check_output(['git','-C',str(bases[repo]),'cat-file','-t',commit]).strip()==b'commit'
 current=subprocess.check_output(['git','-C',str(bases[repo]),'ls-files','-c','-o','--exclude-standard','-z','--','src','tests','pyproject.toml']).decode().split('\0')
 assert sorted(set(p for p in current if p))==sorted(item['path'] for item in files)
 for item in files:
  raw=(bases[repo]/item['path']).read_bytes()
  committed=subprocess.check_output(['git','-C',str(bases[repo]),'show',commit+':'+item['path']])
  assert raw==committed and hashlib.sha256(raw).hexdigest()==item['sha256'],item['path']
  checked+=1
assert checked==858
validation=json.loads((root/'docs/evidence/2026-09-11-v1-05c2e2a-root-validation.json').read_text())
assert validation['core_independent_epoch']['completion']['exit_code']==0
assert all(g['completion']['exit_code']==0 for g in validation['final_paired_epoch']['groups'].values())
assert validation['core_independent_epoch']['pre_post_exact'] is True
assert validation['final_paired_epoch']['pre_post_exact'] is True
actual=json.loads(subprocess.check_output(['bash','-c',validation['static_audit_command']],cwd=root))
