counts={'command_occurrences':0,'python_bodies':0,'expected_python_syntax_errors':0}
def audit_command(value,expected):
 tokens=shlex.split(value); counts['command_occurrences']+=1
 bodies=[]
 if "<<'PY'\n" in value:
  body=value.split("<<'PY'\n",1)[1].rsplit('\nPY',1)[0]; bodies.append(body)
 elif '-c' in tokens and any(t in ('python','python3') for t in tokens): bodies.append(tokens[tokens.index('-c')+1])
 for body in bodies:
  try: ast.parse(body)
  except SyntaxError:
   assert expected, value
   counts['expected_python_syntax_errors']+=1
  else:
   assert not expected, 'declared diagnostic no longer invalid'
   counts['python_bodies']+=1
def walk(value,parent='',expected=False):
 if isinstance(value,dict):
  expected=expected or value.get('expected_python_syntax_error') is True
  for key,item in value.items():
   if isinstance(item,str) and (key in ('command','cmd') or key.endswith('_command') or parent=='commands'):
    audit_command(item,expected)
   else: walk(item,key,expected)
 elif isinstance(value,list):
  for item in value: walk(item,parent,expected)
for name,report in reports: walk(report)
walk(canonical)
assert counts['expected_python_syntax_errors']==1
print(json.dumps({'worktree_and_fixed_commit_files':checked,'evidence_references':len(canonical['evidence_references']),'static_exact':True,**counts},sort_keys=True))
